import random
from itertools import combinations

def has_short_cycle(adj, n, max_len=6):
    # BFS from each vertex to detect cycle of length <= max_len
    for s in range(n):
        # BFS
        dist = [-1]*n
        parent = [-1]*n
        dist[s] = 0
        queue = [s]
        while queue:
            nq = []
            for u in queue:
                for v in adj[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u]+1
                        parent[v] = u
                        if dist[v] <= max_len//2:
                            nq.append(v)
                    elif v != parent[u]:
                        # found cycle
                        if dist[u] + dist[v] + 1 <= max_len:
                            return True
            queue = nq
    return False

def girth_at_least_7(edges, n):
    adj = [set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v); adj[v].add(u)
    # check no cycles length 3,4,5,6
    # For each edge, remove and check shortest path
    for u,v in edges:
        adj[u].remove(v); adj[v].remove(u)
        # BFS shortest path u to v
        dist = {u:0}
        q=[u]
        found = -1
        while q:
            nq=[]
            for x in q:
                for y in adj[x]:
                    if y not in dist:
                        dist[y]=dist[x]+1
                        if y==v:
                            found=dist[y]
                            break
                        nq.append(y)
                if found>0: break
            if found>0: break
            q=nq
        adj[u].add(v); adj[v].add(u)
        if found>0 and found+1 <=6:
            return False
    return True

def is_3colorable(edges, n):
    # Use backtracking
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v); adj[v].append(u)
    color = [-1]*n
    def bt(v):
        if v==n: return True
        used = set()
        for u in adj[v]:
            if color[u]>=0: used.add(color[u])
        for c in range(3):
            if c not in used:
                color[v]=c
                if bt(v+1): return True
        color[v]=-1
        return False
    return bt(0)

