from pysat.solvers import Glucose4
from pysat.card import CardEnc, EncType
from pysat.formula import IDPool

n = 16
vpool = IDPool()
def E(i,j):
    if i>j: i,j=j,i
    return vpool.id(('e',i,j))
# 3-coloring variables
def C(v,c):
    return vpool.id(('c',v,c))

clauses = []
# each vertex has exactly one color
for v in range(n):
    clauses.append([C(v,0),C(v,1),C(v,2)])
    for c1 in range(3):
        for c2 in range(c1+1,3):
            clauses.append([-C(v,c1),-C(v,c2)])

# if edge(u,v), then not same color
for u in range(n):
    for v in range(u+1,n):
        for c in range(3):
            clauses.append([-E(u,v), -C(u,c), -C(v,c)])

# girth >= 7: no cycle of length 3,4,5,6
# For each cycle of length k in K_n, not all edges present
from itertools import combinations, permutations
for k in [3,4,5,6]:
    # enumerate cycles
    for subset in combinations(range(n), k):
        # for each cyclic ordering (fixing first)
        rest = list(subset[1:])
        for perm in permutations(rest):
            seq = (subset[0],)+perm
            # avoid double counting reversed
            if perm[-1] < perm[0]:  # simple canonical form
                continue
            # clause: at least one edge missing
            cl = []
            for i in range(k):
                a,b = seq[i], seq[(i+1)%k]
                cl.append(-E(a,b))
            clauses.append(cl)

# at least 23 edges
edge_vars = [E(i,j) for i in range(n) for j in range(i+1,n)]
print("num edges vars:", len(edge_vars))
print("num clauses so far:", len(clauses))

# cardinality: sum edge_vars >= 23
cnf = CardEnc.atleast(lits=edge_vars, bound=23, vpool=vpool, encoding=EncType.seqcounter)
for c in cnf.clauses:
    clauses.append(c)

print("total clauses:", len(clauses))

solver = Glucose4()
for c in clauses:
    solver.add_clause(c)

print("solving...")
res = solver.solve()
print(res)
if res:
    model = solver.get_model()
    mset = set(model)
    edges = []
    for u in range(n):
        for v in range(u+1,n):
            if E(u,v) in mset:
                edges.append((u,v))
    print("edges:", len(edges))
    print(edges)
    colors = {}
    for v in range(n):
        for c in range(3):
            if C(v,c) in mset:
                colors[v]=c
    print("colors:", colors)

